command:
const hero = game.user.character;
const name = hero.system.parent.name;
const tap = hero.effects.find(fx => fx.name.toUpperCase() === "TAP");
if (!tap) return

// Reset HP
await tap.update({ "changes": [] })
await hero.update({
  "system.health.value": hero.system.health.max,
  "system.mana.current": hero.system.mana.max
})

ChatMessage.create({
  user: game.user._id,
  speaker: ChatMessage.getSpeaker({ token: hero }),
  content: `${name}: (Tap) Resetting max HP / Mana`
});
